function physiologyRelearnLink(chapter,topic,label) {
 return '<a class="study-button" href="#/subject/physiology/chapter/'+chapter+'/topic/'+topic+'">'+label+'</a>';
}
function physiologyRelearnRecall(chapter,topic) {
 const d=physiologyRelearningTopics[chapter.id+'/'+topic.id];
 return '<section class="quiz-panel relearn-recall"><h3>停下來，閉卷說一遍</h3><p>'+d.question+'</p>'
  +'<label>先寫因果與判斷依據<textarea rows="3" style="display:block;box-sizing:border-box;width:100%;max-width:100%;font:inherit;padding:.75rem" placeholder="這裡供暫記，離開頁面不會保存。"></textarea></label>'
  +'<details><summary>回答後核對機轉與常見錯誤</summary><p>'+d.answer+'</p>'
  +'<p><button type="button" class="study-button" data-phys-section="relearn-'+chapter.id+'-'+topic.id+'">回到本節概念銜接</button></p></details></section>';
}
for (const chapter of physiologyChapters) {
 for (const topic of chapter.topics) {
  // Collect citations across all chapters: some examples also appear in other chapter pools.
  for(const match of topic.html.matchAll(/(\d+) 年第 (\d+) 次醫學（([一二])）第 (\d+) 題/g)) {
   physiologyTeachingQuestionIds.add(match[1]+'-'+match[2]+'-'+(match[3]==='一'?'1':'2')+'-'+match[4]);
  }
  for(const match of topic.html.matchAll(/\b(\d{2,3})-(\d) 第\s*(\d+)\s*題/g)) {
   for(const paper of ['1','2'])physiologyTeachingQuestionIds.add(match[1]+'-'+match[2]+'-'+paper+'-'+match[3]);
  }
  const d=physiologyRelearningTopics[chapter.id+'/'+topic.id];
  if(!d) continue;
  const bridge='<section class="relearn-bridge" aria-labelledby="relearn-'+chapter.id+'-'+topic.id+'"><h2 id="relearn-'+chapter.id+'-'+topic.id+'" tabindex="-1">先接回這一節的因果</h2>'+d.intro+'</section>';
  const recall=physiologyRelearnRecall(chapter,topic);
  const marker='<section><h3>用既有原題檢查本節</h3>';
  const clean=topic.html.split(marker)[0].replace(/<nav class="study-actions"[\s\S]*?<\/nav>/,'');
  const section=physiologyTextbooks[chapter.id].find(s=>s.topic===topic.id);
  // Continuous reading now includes the complete detailed topic body and original figures.
  section.html=bridge+clean+recall;
  topic.html=bridge+(topic.html.includes(marker)?topic.html.replace(marker,recall+marker):topic.html+recall);
 }
}
function physiologyRelearningIntro(chapter) {
 const d=physiologyRelearningChapters[chapter.id];
 return '<section class="quiz-panel" aria-label="重新學習路徑">'+d.intro
 +'<details><summary>前置觀念忘記時，從這裡補讀</summary><div class="study-actions">'
 +physiologyPrerequisites[chapter.id].map(([c,t,l])=>physiologyRelearnLink(c,t,l)).join('')+'</div>'
 +'<p>先試著說出各名詞與方向，說不清楚的部分才回讀。補完再回本章繼續。</p></details></section>';
}
const physiologyOriginalReading=physiologyReading;
physiologyReading=function(chapter,root) {
 const original=physiologyOriginalReading(chapter,root);
 return physiologyRelearningIntro(chapter)+original.replace('<section class="quiz-panel"><h2>章末練習</h2>',
 '<article class="lesson relearn-ladder"><h2>從示範走到獨立推理</h2><p>以下是教學自編練習，不列入歷屆題庫或國考成績。先完成紙筆推理，再展開解答。</p>'+physiologyRelearningChapters[chapter.id].practice+'</article><section class="quiz-panel"><h2>章末練習</h2>')
 .replace('先用五題複習題確認推理步驟。再用 20 題章末測驗檢查是否達到 18 題，交卷後可按主題回查錯題。',
 '先完成自編變式與五題原題精讀，再進入章末測驗。可選擇排除正文引用題與此瀏覽器已抽測題；這能減少答案記憶的影響，但無法辨識你在別處看過的題目。18/20 是本次表現，不能單次推定整科已有九成實力。');
};
function physiologyReadAttempts() {
 try { const x=JSON.parse(localStorage.getItem('physiology-relearning-v1')||'{}');return x&&typeof x==='object'&&!Array.isArray(x)?x:{}; } catch { return {}; }
}
function physiologySeenIds() { const x=physiologyReadAttempts();return new Set(Array.isArray(x.seen)?x.seen.filter(id=>typeof id==='string'):[]); }
function physiologyRememberQuestions(selected) {
 try {const x=physiologyReadAttempts(),seen=physiologySeenIds();for(const row of selected)seen.add(row.question.id);x.seen=[...seen];localStorage.setItem('physiology-relearning-v1',JSON.stringify(x));return true;}catch{return false;}
}
function physiologySaveResult(chapter,correct,total,mode) {
 try {const x=physiologyReadAttempts();x.results=Array.isArray(x.results)?x.results:[];x.results.push({chapter:chapter.id,correct,total,mode,date:new Date().toISOString()});x.results=x.results.slice(-50);localStorage.setItem('physiology-relearning-v1',JSON.stringify(x));return true;}catch{return false;}
}
function physiologyRemediation(chapter,group) {
 const i=chapter.exams.notes.findIndex(g=>g.name===group);
 const id=physiologyRemediationTopics[chapter.id][i];
 const topic=chapter.topics.find(t=>t.id===id);
 if(!topic)return '';
 const d=physiologyRelearningTopics[chapter.id+'/'+id];
 return '<details><summary>這個考點不穩時，從哪一步補起？</summary><p>'+d.question+'</p><p>'+d.answer+'</p>'
 +physiologyRelearnLink(chapter.id,id,'回讀 '+topic.title)
 +'<p>辨認錯因：名詞定義、因果方向、公式單位、條件限制或題幹判讀。回讀後先遮住答案重述機轉，再用下一輪未抽過的題目驗證。</p></details>';
}

